CREATE   PROCEDURE [Adobe].[usp_Upsert_mobile_attributes]
AS
BEGIN
	/*
		Raj Maddala, 2025-02-15

	*/

	MERGE [Adobe].[mobile_attributes] tgt
	USING [Staging_Adobe].[mobile_attributes] src
		ON tgt.[mobile_id] = src.[Prop_0]
	WHEN MATCHED THEN UPDATE SET
		tgt.[mobile_id] = CAST(src.[Prop_0] AS BIGINT),
		tgt.[Manufacturer] = CAST(src.[Prop_1] AS NVARCHAR(100)),
		tgt.[Device] = CAST(src.[Prop_2] AS NVARCHAR(255)),
		tgt.[Device Type] = CAST(src.[Prop_3] AS NVARCHAR(50)),
		tgt.[Operating System] = CAST(src.[Prop_4] AS NVARCHAR(50)),
		tgt.[Diagonal Screen Size] = CAST(src.[Prop_5] AS NVARCHAR(50)),
		tgt.[Screen Height] = CAST(src.[Prop_6] AS NVARCHAR(50)),
		tgt.[Screen Width] = CAST(src.[Prop_7] AS NVARCHAR(50)),
		tgt.[Cookie Support] = CAST(src.[Prop_8] AS NVARCHAR(50)),
		tgt.[Color Depth] = CAST(src.[Prop_9] AS NVARCHAR(50)),
		tgt.[MP3 Audio Support] = CAST(src.[Prop_10] AS NVARCHAR(50)),
		tgt.[AAC Audio Support] = CAST(src.[Prop_11] AS NVARCHAR(50)),
		tgt.[AMR Audio Support] = CAST(src.[Prop_12] AS NVARCHAR(50)),
		tgt.[Midi Monophonic Audio Support] = CAST(src.[Prop_13] AS NVARCHAR(50)),
		tgt.[Midi Polyphonic Audio Support] = CAST(src.[Prop_14] AS NVARCHAR(50)),
		tgt.[QCELP Audio Support] = CAST(src.[Prop_15] AS NVARCHAR(50)),
		tgt.[GIF87 Image Support] = CAST(src.[Prop_16] AS NVARCHAR(50)),
		tgt.[GIF89a Image Support] = CAST(src.[Prop_17] AS NVARCHAR(50)),
		tgt.[PNG Image Support] = CAST(src.[Prop_18] AS NVARCHAR(50)),
		tgt.[JPG Image Support] = CAST(src.[Prop_19] AS NVARCHAR(50)),
		tgt.[3GPP Video Support] = CAST(src.[Prop_20] AS NVARCHAR(50)),
		tgt.[MPEG4 Video Support] = CAST(src.[Prop_21] AS NVARCHAR(50)),
		tgt.[3GPP2 Video Support] = CAST(src.[Prop_22] AS NVARCHAR(50)),
		tgt.[WMV Video Support] = CAST(src.[Prop_23] AS NVARCHAR(50)),
		tgt.[MPEG4 Part 2 Video Support] = CAST(src.[Prop_24] AS NVARCHAR(50)),
		tgt.[Stream MP4 AAC LC Video Support] = CAST(src.[Prop_25] AS NVARCHAR(50)),
		tgt.[Stream 3GP H264 Level 10b Video Support] = CAST(src.[Prop_26] AS NVARCHAR(50)),
		tgt.[Stream 3GP AAC LC Video Support] = CAST(src.[Prop_27] AS NVARCHAR(50)),
		tgt.[3GP AAC LC Video Support] = CAST(src.[Prop_28] AS NVARCHAR(50)),
		tgt.[Stream MP4 H264 Level 11 Video Support] = CAST(src.[Prop_29] AS NVARCHAR(50)),
		tgt.[Stream MP4 H264 Level 13 Video Support] = CAST(src.[Prop_30] AS NVARCHAR(50)),
		tgt.[Stream 3GP H264 Level 12 Video Support] = CAST(src.[Prop_31] AS NVARCHAR(50)),
		tgt.[Stream 3GP H264 Level 11 Video Support] = CAST(src.[Prop_32] AS NVARCHAR(50)),
		tgt.[Stream 3GP H264 Level 10 Video Support] = CAST(src.[Prop_33] AS NVARCHAR(50)),
		tgt.[Stream 3GP H264 Level 13 Video Support] = CAST(src.[Prop_34] AS NVARCHAR(50)),
		tgt.[3GP AMR NB Video Support] = CAST(src.[Prop_35] AS NVARCHAR(50)),
		tgt.[3GP AMR WB Video Support] = CAST(src.[Prop_36] AS NVARCHAR(50)),
		tgt.[MP4 H264 Level 11 Video Support] = CAST(src.[Prop_37] AS NVARCHAR(50)),
		tgt.[3GP H263 Video Support] = CAST(src.[Prop_38] AS NVARCHAR(50)),
		tgt.[MP4 H264 Level 13 Video Support] = CAST(src.[Prop_39] AS NVARCHAR(50)),
		tgt.[Stream 3GP H263 Video Support] = CAST(src.[Prop_40] AS NVARCHAR(50)),
		tgt.[Stream 3GP AMR WB Video Support] = CAST(src.[Prop_41] AS NVARCHAR(50)),
		tgt.[3GP H264 Level 10b Video Support] = CAST(src.[Prop_42] AS NVARCHAR(50)),
		tgt.[MP4 ACC LC Video Support] = CAST(src.[Prop_43] AS NVARCHAR(50)),
		tgt.[Stream 3GP AMR NB Video Support] = CAST(src.[Prop_44] AS NVARCHAR(50)),
		tgt.[3GP H264 Level 10 Video Support] = CAST(src.[Prop_45] AS NVARCHAR(50)),
		tgt.[3GP H264 Level 13 Video Support] = CAST(src.[Prop_46] AS NVARCHAR(50)),
		tgt.[3GP H264 Level 11 Video Support] = CAST(src.[Prop_47] AS NVARCHAR(50)),
		tgt.[3GP H264 Level 12 Video Support] = CAST(src.[Prop_48] AS NVARCHAR(50)),
		tgt.[Stream HTTP Live Streaming Video Support] = CAST(src.[Prop_49] AS NVARCHAR(50)),
		tgt.[source_file_name] = CAST(src.[source_file_name] AS NVARCHAR(50))
	WHEN NOT MATCHED BY TARGET THEN INSERT
	(
		[mobile_id],
		[Manufacturer],
		[Device],
		[Device Type],
		[Operating System],
		[Diagonal Screen Size],
		[Screen Height],
		[Screen Width],
		[Cookie Support],
		[Color Depth],
		[MP3 Audio Support],
		[AAC Audio Support],
		[AMR Audio Support],
		[Midi Monophonic Audio Support],
		[Midi Polyphonic Audio Support],
		[QCELP Audio Support],
		[GIF87 Image Support],
		[GIF89a Image Support],
		[PNG Image Support],
		[JPG Image Support],
		[3GPP Video Support],
		[MPEG4 Video Support],
		[3GPP2 Video Support],
		[WMV Video Support],
		[MPEG4 Part 2 Video Support],
		[Stream MP4 AAC LC Video Support],
		[Stream 3GP H264 Level 10b Video Support],
		[Stream 3GP AAC LC Video Support],
		[3GP AAC LC Video Support],
		[Stream MP4 H264 Level 11 Video Support],
		[Stream MP4 H264 Level 13 Video Support],
		[Stream 3GP H264 Level 12 Video Support],
		[Stream 3GP H264 Level 11 Video Support],
		[Stream 3GP H264 Level 10 Video Support],
		[Stream 3GP H264 Level 13 Video Support],
		[3GP AMR NB Video Support],
		[3GP AMR WB Video Support],
		[MP4 H264 Level 11 Video Support],
		[3GP H263 Video Support],
		[MP4 H264 Level 13 Video Support],
		[Stream 3GP H263 Video Support],
		[Stream 3GP AMR WB Video Support],
		[3GP H264 Level 10b Video Support],
		[MP4 ACC LC Video Support],
		[Stream 3GP AMR NB Video Support],
		[3GP H264 Level 10 Video Support],
		[3GP H264 Level 13 Video Support],
		[3GP H264 Level 11 Video Support],
		[3GP H264 Level 12 Video Support],
		[Stream HTTP Live Streaming Video Support],
		[source_file_name]
	)
	VALUES
	(
		CAST(src.[Prop_0] AS BIGINT),
		CAST(src.[Prop_1] AS NVARCHAR(100)),
		CAST(src.[Prop_2] AS NVARCHAR(255)),
		CAST(src.[Prop_3] AS NVARCHAR(50)),
		CAST(src.[Prop_4] AS NVARCHAR(50)),
		CAST(src.[Prop_5] AS NVARCHAR(50)),
		CAST(src.[Prop_6] AS NVARCHAR(50)),
		CAST(src.[Prop_7] AS NVARCHAR(50)),
		CAST(src.[Prop_8] AS NVARCHAR(50)),
		CAST(src.[Prop_9] AS NVARCHAR(50)),
		CAST(src.[Prop_10] AS NVARCHAR(50)),
		CAST(src.[Prop_11] AS NVARCHAR(50)),
		CAST(src.[Prop_12] AS NVARCHAR(50)),
		CAST(src.[Prop_13] AS NVARCHAR(50)),
		CAST(src.[Prop_14] AS NVARCHAR(50)),
		CAST(src.[Prop_15] AS NVARCHAR(50)),
		CAST(src.[Prop_16] AS NVARCHAR(50)),
		CAST(src.[Prop_17] AS NVARCHAR(50)),
		CAST(src.[Prop_18] AS NVARCHAR(50)),
		CAST(src.[Prop_19] AS NVARCHAR(50)),
		CAST(src.[Prop_20] AS NVARCHAR(50)),
		CAST(src.[Prop_21] AS NVARCHAR(50)),
		CAST(src.[Prop_22] AS NVARCHAR(50)),
		CAST(src.[Prop_23] AS NVARCHAR(50)),
		CAST(src.[Prop_24] AS NVARCHAR(50)),
		CAST(src.[Prop_25] AS NVARCHAR(50)),
		CAST(src.[Prop_26] AS NVARCHAR(50)),
		CAST(src.[Prop_27] AS NVARCHAR(50)),
		CAST(src.[Prop_28] AS NVARCHAR(50)),
		CAST(src.[Prop_29] AS NVARCHAR(50)),
		CAST(src.[Prop_30] AS NVARCHAR(50)),
		CAST(src.[Prop_31] AS NVARCHAR(50)),
		CAST(src.[Prop_32] AS NVARCHAR(50)),
		CAST(src.[Prop_33] AS NVARCHAR(50)),
		CAST(src.[Prop_34] AS NVARCHAR(50)),
		CAST(src.[Prop_35] AS NVARCHAR(50)),
		CAST(src.[Prop_36] AS NVARCHAR(50)),
		CAST(src.[Prop_37] AS NVARCHAR(50)),
		CAST(src.[Prop_38] AS NVARCHAR(50)),
		CAST(src.[Prop_39] AS NVARCHAR(50)),
		CAST(src.[Prop_40] AS NVARCHAR(50)),
		CAST(src.[Prop_41] AS NVARCHAR(50)),
		CAST(src.[Prop_42] AS NVARCHAR(50)),
		CAST(src.[Prop_43] AS NVARCHAR(50)),
		CAST(src.[Prop_44] AS NVARCHAR(50)),
		CAST(src.[Prop_45] AS NVARCHAR(50)),
		CAST(src.[Prop_46] AS NVARCHAR(50)),
		CAST(src.[Prop_47] AS NVARCHAR(50)),
		CAST(src.[Prop_48] AS NVARCHAR(50)),
		CAST(src.[Prop_49] AS NVARCHAR(50)),
		CAST(src.[source_file_name] AS NVARCHAR(50))
	);

END
